document.getElementById("click-area").addEventListener("click", (e) => {
  console.log(e.button); // zazwyczaj 0 dla zwyklego klikniecia lewym przyciskiem
});

const clickArea = document.getElementById("click-area");
const coords = document.getElementById("coords");

clickArea.addEventListener("mousemove", (e) => {
  coords.textContent = "clientX: " + e.clientX;
});

const clickArea = document.getElementById("click-area");
const coords = document.getElementById("coords");

clickArea.addEventListener("mousemove", (e) => {
  coords.textContent = `offset: ${e.offsetX}, ${e.offsetY}`;
});

const clickArea = document.getElementById("click-area");

clickArea.addEventListener("mouseenter", () => {
  clickArea.style.borderColor = "#e91e63";
});
clickArea.addEventListener("mouseleave", () => {
  clickArea.style.borderColor = "#1565c0";
});

const eventLog = document.getElementById("event-log");

eventLog.addEventListener("mouseenter", () => {
  eventLog.style.opacity = "0.5";
});
eventLog.addEventListener("mouseleave", () => {
  eventLog.style.opacity = "1";
});

// mouseover/mouseout BUBBLINGUJA - wystrzeliwuja PONOWNIE przy kazdym
// przejsciu kursora miedzy WEWNETRZNYMI elementami danego kontenera
// (np. z <div> na zagniezdzony w nim <span>), co powoduje 'miganie'
// efektu (np. tla) przy kazdym takim przejsciu.
//
// mouseenter/mouseleave NIE bubbinguja - reaguja WYLACZNIE na faktyczne
// wejscie/wyjscie z CALEGO obszaru elementu (wraz z jego dziecmi),
// ignorujac wewnetrzne przejscia. Dlatego dla prostych efektow hover sa
// zazwyczaj wlasciwszym, bardziej stabilnym wyborem.
